import { useState, type ChangeEvent } from 'react';
import { withConfiguration, FormField, FormControl, FieldValueList, Select, Option } from '@pega/cosmos-react-core';
import '../shared/create-nonce';
import StyledPegaExtensionsCoverageLevelWrapper from './styles';

/** One entry of a property's value list, as the platform supplies it. */
type PicklistItem = { key: string; text?: string; value?: string };

/**
 * Dropdown for selecting a policy coverage level from the property value list.
 *
 * Generated by tools/generator. The props below are emitted from the same spec
 * as config.json, so the property panel and this type cannot drift.
 *
 * Authored properties:
 * (none)
 */
type PegaExtensionsCoverageLevelProps = {
  /** field label */
  label: string;
  /** value supplied by the platform */
  value: string;
  /** options from the property's local list */
  datasource?: PicklistItem[] | { source?: PicklistItem[] };
  /** placeholder text */
  placeholder?: string;
  /** helper text */
  helperText?: string;
  /** 'datapage' when the options come from a data page */
  listType?: string;
  /** validation message */
  validatemessage?: string;
  /** hide the label */
  hideLabel?: boolean;
  /** is the field disabled */
  disabled?: boolean;
  /** is the field read-only */
  readOnly?: boolean;
  /** is the field required */
  required?: boolean;
  /** test id */
  testId?: string;
  /** display mode */
  displayMode?: 'DISPLAY_ONLY' | 'LABELS_LEFT' | '';
  /** PConnect accessor */
  getPConnect: any;
};

export const PegaExtensionsCoverageLevel = (props: PegaExtensionsCoverageLevelProps) => {
  const {
    label,
    value,
    datasource,
    listType,
    placeholder,
    helperText,
    validatemessage,
    hideLabel = false,
    disabled = false,
    readOnly = false,
    required = false,
    testId,
    displayMode,
    getPConnect,
  } = props;

  const pConn = getPConnect();
  const actions = pConn.getActionsApi();
  const propName: string = pConn.getStateProps().value;

  /* Options come from the property: a local list arrives on `datasource`, a
     data page on `listOutput`. Nothing about the list is hardcoded here. */
  const isDataPage = listType === 'datapage';
  const rawItems = isDataPage ? pConn.getConfigProps()?.listOutput : datasource;
  const items: PicklistItem[] = Array.isArray(rawItems) ? rawItems : (rawItems?.source ?? []);
  const labelFor = (item: PicklistItem) => (isDataPage ? item.text : item.value) ?? String(item.key);

  /* The stored value is the option key; the label is what a reader expects. */
  const selectedLabel =
    items.find((item) => String(item.key) === String(value ?? ''))?.[isDataPage ? 'text' : 'value'] ??
    String(value ?? '');

  const [status, setStatus] = useState<'error' | undefined>(undefined);

  const handleChange = (event: ChangeEvent<HTMLSelectElement>) => {
    actions.updateFieldValue(propName, event.target.value);
  };

  const handleBlur = () => {
    actions.triggerFieldChange(propName, value);
    setStatus(validatemessage ? 'error' : undefined);
  };

  if (displayMode === 'DISPLAY_ONLY') {
    return <StyledPegaExtensionsCoverageLevelWrapper>{selectedLabel}</StyledPegaExtensionsCoverageLevelWrapper>;
  }

  if (displayMode === 'LABELS_LEFT') {
    return (
      <StyledPegaExtensionsCoverageLevelWrapper>
        <FieldValueList
          variant={hideLabel ? 'stacked' : 'inline'}
          data-testid={testId}
          fields={[{ id: '1', name: hideLabel ? '' : label, value: selectedLabel }]}
        />
      </StyledPegaExtensionsCoverageLevelWrapper>
    );
  }

  return (
    <StyledPegaExtensionsCoverageLevelWrapper>
      <FormField
        label={label}
        labelHidden={hideLabel}
        info={validatemessage || helperText}
        status={status}
        testId={testId}
        disabled={disabled}
        readOnly={readOnly}
        required={required}
      >
        <FormControl>
          <Select
            value={value ?? ''}
            disabled={disabled}
            readOnly={readOnly}
            required={required}
            onChange={handleChange}
            onBlur={handleBlur}
            testId={testId}
          >
            {placeholder ? <Option value=''>{placeholder}</Option> : null}
            {items.map((item) => (
              <Option key={String(item.key)} value={String(item.key)}>
                {labelFor(item)}
              </Option>
            ))}
          </Select>
        </FormControl>
      </FormField>
    </StyledPegaExtensionsCoverageLevelWrapper>
  );
};

export default withConfiguration(PegaExtensionsCoverageLevel);
